 */
defined('ABSPATH') || exit;

final class Trofy_AppForms {
    private const VERSION='2.0.2'; private const ACCESS_TTL=28800; private const ACCESS_COOKIE='trofy_appforms_access'; private static $db=null;
    public static function init():void{add_shortcode('appforms-301',[__CLASS__,'render_application_form']);add_shortcode('event_registration',[__CLASS__,'render_application_form']);add_shortcode('appforms-302',[__CLASS__,'render_applications']);add_filter('query_vars',static function($v){$v[]='season_id';$v[]='event_id';return$v;});add_action('admin_menu',[__CLASS__,'admin_menu']);add_action('admin_enqueue_scripts',[__CLASS__,'admin_assets']);add_action('wp_enqueue_scripts',[__CLASS__,'frontend_assets']);add_action('wp_ajax_trofy_load_events',[__CLASS__,'ajax_load_events']);add_action('wp_ajax_trofy_save_settings',[__CLASS__,'ajax_save_settings']);add_action('wp_ajax_trofy_delete_application',[__CLASS__,'ajax_delete_application']);add_action('admin_post_nopriv_trofy_submit_application',[__CLASS__,'submit_application']);add_action('admin_post_trofy_submit_application',[__CLASS__,'submit_application']);add_action('admin_post_trofy_public_login',[__CLASS__,'public_login']);add_action('admin_post_nopriv_trofy_public_login',[__CLASS__,'public_login']);add_action('admin_post_trofy_public_logout',[__CLASS__,'public_logout']);add_action('admin_post_nopriv_trofy_public_logout',[__CLASS__,'public_logout']);add_action('admin_post_trofy_export',[__CLASS__,'export_excel']);add_action('admin_post_nopriv_trofy_export',[__CLASS__,'export_excel']);}
    private static function db(){if(self::$db instanceof mysqli)return self::$db;$host=defined('TROFY_APPFORMS_DB_HOST')?TROFY_APPFORMS_DB_HOST:(defined('APPFORMS_DB_HOST')?APPFORMS_DB_HOST:null);$user=defined('TROFY_APPFORMS_DB_USER')?TROFY_APPFORMS_DB_USER:(defined('APPFORMS_DB_USER')?APPFORMS_DB_USER:null);$pass=defined('TROFY_APPFORMS_DB_PASS')?TROFY_APPFORMS_DB_PASS:(defined('APPFORMS_DB_PASS')?APPFORMS_DB_PASS:null);$name=defined('TROFY_APPFORMS_DB_NAME')?TROFY_APPFORMS_DB_NAME:(defined('APPFORMS_DB_NAME')?APPFORMS_DB_NAME:null);if(!$host||!$user||!$name)throw new RuntimeException('Не настроено подключение к БД заявок. Добавьте TROFY_APPFORMS_DB_* в wp-config.php.');mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);self::$db=new mysqli($host,$user,$pass??'',$name);self::$db->set_charset('utf8mb4');return self::$db;}
    private static function settings():?array{$s=absint(get_query_var('season_id'));$e=absint(get_query_var('event_id'));if($s&&$e){$st=self::db()->prepare("SELECT e.event_id,e.season_id,app.pass,e.event_name,s.season_name,e.event_date FROM Events e JOIN Seasons s ON e.season_id=s.season_id LEFT JOIN appsettings app ON app.id=1 WHERE e.event_id=? AND e.season_id=? LIMIT 1");$st->bind_param('ii',$e,$s);$st->execute();$r=$st->get_result()->fetch_assoc();if($r){if(empty($r['pass'])){$f=self::db()->query('SELECT pass FROM appsettings WHERE id=1 LIMIT 1')->fetch_assoc();$r['pass']=$f['pass']??'';}return$r;}}$r=self::db()->query("SELECT app.event_id,app.season_id,app.pass,e.event_name,s.season_name,e.event_date FROM appsettings app JOIN Seasons s ON app.season_id=s.season_id JOIN Events e ON app.event_id=e.event_id ORDER BY app.id ASC LIMIT 1")->fetch_assoc();return$r?:null;}
    private static function redirect(string $u,array $a=[]):void{wp_safe_redirect(add_query_arg($a,$u));exit;} private static function current_url():string{return esc_url_raw(remove_query_arg(['r','login'],home_url(wp_unslash($_SERVER['REQUEST_URI']??'/'))));} private static function applications_url(?array $s=null):string{$u=home_url('/заявки/');$a=$s['season_id']??absint(get_query_var('season_id'));$b=$s['event_id']??absint(get_query_var('event_id'));return($a&&$b)?add_query_arg(['season_id'=>$a,'event_id'=>$b],$u):$u;} private static function has_public_access():bool{if(empty($_COOKIE[self::ACCESS_COOKIE]))return false;$t=sanitize_text_field(wp_unslash($_COOKIE[self::ACCESS_COOKIE]));return(bool)get_transient('trofy_appforms_access_'.hash('sha256',$t));} private static function issue_public_access():void{$t=bin2hex(random_bytes(32));set_transient('trofy_appforms_access_'.hash('sha256',$t),true,self::ACCESS_TTL);setcookie(self::ACCESS_COOKIE,$t,['expires'=>time()+self::ACCESS_TTL,'path'=>COOKIEPATH?:'/','secure'=>is_ssl(),'httponly'=>true,'samesite'=>'Lax']);} private static function revoke_public_access():void{if(!empty($_COOKIE[self::ACCESS_COOKIE])){$t=sanitize_text_field(wp_unslash($_COOKIE[self::ACCESS_COOKIE]));delete_transient('trofy_appforms_access_'.hash('sha256',$t));}setcookie(self::ACCESS_COOKIE,'',['expires'=>time()-3600,'path'=>COOKIEPATH?:'/','secure'=>is_ssl(),'httponly'=>true,'samesite'=>'Lax']);}
    public static function frontend_assets():void{wp_register_style('trofy-appforms',false,[],self::VERSION);wp_enqueue_style('trofy-appforms');wp_add_inline_style('trofy-appforms',self::frontend_css());} public static function admin_assets(string $hook):void{if($hook!=='toplevel_page_app')return;wp_enqueue_style('dashicons');wp_register_style('trofy-appforms-admin',false,[],self::VERSION);wp_enqueue_style('trofy-appforms-admin');wp_add_inline_style('trofy-appforms-admin',self::admin_css());wp_enqueue_script('jquery');wp_add_inline_script('jquery','window.TrofyAppForms='.wp_json_encode(['ajaxurl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('trofy_appforms_admin')]).';','before');wp_add_inline_script('jquery',self::admin_js(),'after');} public static function admin_menu():void{add_menu_page('Заявки','Заявки','manage_options','app',[__CLASS__,'admin_page'],'dashicons-clipboard',20);}
    public static function admin_page():void{if(!current_user_can('manage_options'))wp_die('Недостаточно прав.');try{$s=self::settings();$seasons=self::db()->query('SELECT season_id,season_name FROM Seasons ORDER BY season_id DESC')->fetch_all(MYSQLI_ASSOC);$events=[];if($s){$st=self::db()->prepare('SELECT event_id,event_name,event_date FROM Events WHERE season_id=? ORDER BY event_date,event_id');$st->bind_param('i',$s['season_id']);$st->execute();$events=$st->get_result()->fetch_all(MYSQLI_ASSOC);}$rows=$s?self::get_applications((int)$s['season_id'],(int)$s['event_id']):[];}catch(Throwable $e){echo'<div class="wrap"><div class="notice notice-error"><p>'.esc_html($e->getMessage()).'</p></div></div>';return;}?><div class="wrap trofy-admin"><div class="trofy-admin-head"><div><span class="trofy-eyebrow">TROFY APPFORMS</span><h1>Заявки</h1><p>Управление регистрацией экипажей</p></div><?php if($s):?><a class="button button-primary trofy-export" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=trofy_export&scope=admin'),'trofy_export')); ?>">Скачать Excel</a><?php endif;?></div><div class="trofy-settings-card"><div class="trofy-field"><label>Сезон</label><select id="trofy-season"><option value="">Выберите сезон</option><?php foreach($seasons as $x):?><option value="<?php echo(int)$x['season_id'];?>" <?php selected($s['season_id']??0,$x['season_id']);?>><?php echo esc_html($x['season_name']);?></option><?php endforeach;?></select></div><div class="trofy-field"><label>Этап</label><select id="trofy-event"><?php foreach($events as $x):?><option value="<?php echo(int)$x['event_id'];?>" <?php selected($s['event_id']??0,$x['event_id']);?>><?php echo esc_html($x['event_name']);?></option><?php endforeach;?></select></div><div class="trofy-field"><label>Пароль для списка</label><input type="password" id="trofy-pass" placeholder="Оставьте пустым, чтобы не менять"><small>Хранится в виде хеша.</small></div><button type="button" class="button button-primary" id="trofy-save">Сохранить</button></div><?php if($s):?><div class="trofy-stats"><div><strong><?php echo count($rows);?></strong><span>всего</span></div><?php foreach(['Полироль','Стандарт','Туризм','Спорт'] as $c):$n=count(array_filter($rows,static fn($r)=>$r['class']===$c));?><div><strong><?php echo$n;?></strong><span><?php echo esc_html($c);?></span></div><?php endforeach;?></div><div class="trofy-toolbar"><input type="search" id="trofy-search" placeholder="Поиск..."><select id="trofy-class"><option value="">Все классы</option><option>Полироль</option><option>Стандарт</option><option>Туризм</option><option>Спорт</option></select></div><div class="trofy-table-wrap"><table class="trofy-table"><thead><tr><th>#</th><th>Дата</th><th>Класс</th><th>Пилот</th><th>Штурман</th><th>Город</th><th>Автомобиль</th><th>Телефон</th><th></th></tr></thead><tbody id="trofy-rows"><?php self::render_rows($rows);?></tbody></table></div><?php endif;?><div id="trofy-admin-message"></div></div><?php}
    private static function get_applications(int $s,int $e):array{$st=self::db()->prepare("SELECT id,class,namePilot,nameShturman,city,car,tel,DATE_FORMAT(time,'%d.%m.%Y %H:%i') formatted_time FROM appparticipation WHERE season_id=? AND event_id=? ORDER BY time DESC");$st->bind_param('ii',$s,$e);$st->execute();return$st->get_result()->fetch_all(MYSQLI_ASSOC);} private static function render_rows(array $rows):void{if(!$rows){echo'<tr><td colspan="9" class="trofy-empty">Заявок пока нет</td></tr>';return;}foreach($rows as $i=>$r){$q=strtolower(implode(' ',[$r['class'],$r['namePilot'],$r['nameShturman'],$r['city'],$r['car'],$r['tel']]));echo'<tr data-class="'.esc_attr($r['class']).'" data-search="'.esc_attr($q).'"><td data-label="#">'.($i+1).'</td><td data-label="Дата">'.esc_html($r['formatted_time']).'</td><td data-label="Класс">'.esc_html($r['class']).'</td><td data-label="Пилот"><strong>'.esc_html($r['namePilot']).'</strong></td><td data-label="Штурман">'.esc_html($r['nameShturman']).'</td><td data-label="Город">'.esc_html($r['city']).'</td><td data-label="Автомобиль">'.esc_html($r['car']).'</td><td data-label="Телефон"><a href="tel:'.esc_attr($r['tel']).'">'.esc_html($r['tel']).'</a></td><td><button type="button" class="button-link-delete trofy-delete" data-id="'.(int)$r['id'].'">Удалить</button></td></tr>';}}
    public static function ajax_load_events():void{check_ajax_referer('trofy_appforms_admin','nonce');if(!current_user_can('manage_options'))wp_send_json_error('Недостаточно прав.',403);$s=absint($_POST['season_id']??0);$st=self::db()->prepare('SELECT event_id,event_name FROM Events WHERE season_id=? ORDER BY event_date,event_id');$st->bind_param('i',$s);$st->execute();wp_send_json_success($st->get_result()->fetch_all(MYSQLI_ASSOC));}
    public static function ajax_save_settings():void{check_ajax_referer('trofy_appforms_admin','nonce');if(!current_user_can('manage_options'))wp_send_json_error('Недостаточно прав.',403);try{$s=absint($_POST['season_id']??0);$e=absint($_POST['event_id']??0);$p=isset($_POST['pass'])?trim(wp_unslash($_POST['pass'])):'';if(!$s||!$e)wp_send_json_error('Выберите сезон и этап.');$c=self::db()->prepare('SELECT event_id FROM Events WHERE event_id=? AND season_id=? LIMIT 1');$c->bind_param('ii',$e,$s);$c->execute();if(!$c->get_result()->fetch_assoc())wp_send_json_error('Этап не относится к сезону.');if($p!==''){$h=wp_hash_password($p);$st=self::db()->prepare('UPDATE appsettings SET season_id=?,event_id=?,pass=? WHERE id=1');$st->bind_param('iis',$s,$e,$h);}else{$st=self::db()->prepare('UPDATE appsettings SET season_id=?,event_id=? WHERE id=1');$st->bind_param('ii',$s,$e);}$st->execute();wp_send_json_success('Настройки сохранены.');}catch(Throwable $e){wp_send_json_error('Не удалось сохранить настройки.');}}
    public static function ajax_delete_application():void{check_ajax_referer('trofy_appforms_admin','nonce');if(!current_user_can('manage_options'))wp_send_json_error('Недостаточно прав.',403);$id=absint($_POST['id']??0);if(!$id)wp_send_json_error('Некорректная заявка.');$st=self::db()->prepare('DELETE FROM appparticipation WHERE id=?');$st->bind_param('i',$id);$st->execute();wp_send_json_success();}
    public static function render_application_form():string{try{$s=self::settings();}catch(Throwable $e){return'<div class="trofy-alert">Ошибка подключения к заявкам.</div>';}if(!$s)return'<div class="trofy-alert">Не удалось загрузить настройки мероприятия.</div>';$d=new DateTime($s['event_date']);$d->modify('-17 hours');if(new DateTime()>=$d)return'<div class="trofy-closed"><h3>Приём заявок окончен</h3><p><a href="'.esc_url(self::applications_url($s)).'">Список заявок</a></p></div>';$u=self::current_url();ob_start();?><div class="trofy-form"><div class="trofy-form-head"><span>РЕГИСТРАЦИЯ</span><h2><?php echo esc_html($s['event_name']);?></h2><p><?php echo esc_html($s['season_name']);?></p></div><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="trofy_submit_application"><?php wp_nonce_field('trofy_submit_application','_wpnonce');?><input type="hidden" name="redirect_to" value="<?php echo esc_attr($u);?>"><input type="text" name="website" class="trofy-hp" tabindex="-1" autocomplete="off"><?php self::form_input('namePilot','ФИО пилота',true);self::form_input('nameShturman','ФИО штурмана');self::form_input('tel','Телефон',true,'tel');self::form_input('car','Автомобиль',true);self::form_input('city','Город',true);?><div class="trofy-input"><label>Класс *</label><div class="trofy-radios"><?php foreach(['Полироль','Стандарт','Туризм','Спорт'] as $c):?><label><input type="radio" name="class" value="<?php echo esc_attr($c);?>" required><span><?php echo esc_html($c);?></span></label><?php endforeach;?></div></div><input type="hidden" name="season_id" value="<?php echo(int)$s['season_id'];?>"><input type="hidden" name="event_id" value="<?php echo(int)$s['event_id'];?>"><button class="trofy-submit" type="submit">Отправить заявку <span>→</span></button></form></div><?php return ob_get_clean();} private static function form_input(string $n,string $l,bool $r=false,string $t='text'):void{echo'<div class="trofy-input"><label for="trofy-'.esc_attr($n).'">'.esc_html($l).($r?' *':'').'</label><input id="trofy-'.esc_attr($n).'" type="'.esc_attr($t).'" name="'.esc_attr($n).'" maxlength="200"'.($r?' required':'').'></div>';}
    public static function submit_application():void{$u=!empty($_POST['redirect_to'])?esc_url_raw(wp_unslash($_POST['redirect_to'])):home_url('/заявка/');if(!wp_validate_redirect($u,home_url('/заявка/')))$u=home_url('/заявка/');if(empty($_POST['_wpnonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce'])),'trofy_submit_application'))self::redirect($u,['r'=>'err']);if(!empty($_POST['website']))self::redirect($u,['r'=>'ok']);try{$f=['namePilot','nameShturman','tel','class','car','city'];$d=[];foreach($f as $x)$d[$x]=isset($_POST[$x])?sanitize_text_field(wp_unslash($_POST[$x])):'';$s=absint($_POST['season_id']??0);$e=absint($_POST['event_id']??0);if(!$d['namePilot']||!$d['tel']||!$d['class']||!$d['car']||!$d['city']||!$s||!$e)throw new RuntimeException();$c=self::db()->prepare('SELECT event_id,event_date FROM Events WHERE event_id=? AND season_id=? LIMIT 1');$c->bind_param('ii',$e,$s);$c->execute();$ev=$c->get_result()->fetch_assoc();if(!$ev)throw new RuntimeException();$dl=new DateTime($ev['event_date']);$dl->modify('-17 hours');if(new DateTime()>=$dl)throw new RuntimeException();if(!in_array($d['class'],['Полироль','Стандарт','Туризм','Спорт'],true))throw new RuntimeException();$st=self::db()->prepare('INSERT INTO appparticipation (time,namePilot,nameShturman,tel,class,car,city,season_id,event_id) VALUES (NOW(),?,?,?,?,?,?,?,?)');$st->bind_param('ssssssii',$d['namePilot'],$d['nameShturman'],$d['tel'],$d['class'],$d['car'],$d['city'],$s,$e);$st->execute();wp_mail(get_option('admin_email'),'Новая заявка',"Новая заявка\nПилот: {$d['namePilot']}\nШтурман: {$d['nameShturman']}\nТел.: {$d['tel']}\nКласс: {$d['class']}\nАвто: {$d['car']}\nГород: {$d['city']}");self::redirect($u,['r'=>'ok']);}catch(Throwable $e){error_log('Trofy AppForms: '.$e->getMessage());self::redirect($u,['r'=>'err']);}}
    public static function render_applications():string{try{$s=self::settings();}catch(Throwable $e){return'<div class="trofy-alert">Ошибка подключения к заявкам.</div>';}if(!$s)return'<div class="trofy-alert">Не удалось загрузить настройки.</div>';if(!self::has_public_access()){$err=isset($_GET['login'])?'<div class="trofy-login-error">Неверный пароль.</div>':'';$u=self::applications_url($s);return'<div class="trofy-login"><h2>Доступ к заявкам</h2><p>Введите пароль, чтобы посмотреть список экипажей.</p>'.$err.'<form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="trofy_public_login"><input type="hidden" name="redirect_to" value="'.esc_attr($u).'"><input type="hidden" name="season_id" value="'.(int)$s['season_id'].'"><input type="hidden" name="event_id" value="'.(int)$s['event_id'].'"><input type="password" name="password" required><button type="submit">Показать заявки</button></form></div>';} $rows=self::get_applications((int)$s['season_id'],(int)$s['event_id']);ob_start();?><div class="trofy-public"><div class="trofy-public-head"><div><span>СПИСОК ЗАЯВОК</span><h2><?php echo esc_html($s['event_name']);?></h2><p><?php echo esc_html($s['season_name']);?></p></div><div class="trofy-public-actions"><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=trofy_export&scope=public&season_id='.(int)$s['season_id'].'&event_id='.(int)$s['event_id']),'trofy_export'));?>">↓ Excel</a><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=trofy_public_logout&redirect_to='.rawurlencode(self::applications_url($s))),'trofy_public_logout'));?>">Выйти</a></div></div><div class="trofy-public-count">Всего экипажей: <strong><?php echo count($rows);?></strong></div><div class="trofy-public-grid"><?php foreach($rows as $i=>$r):?><article><div class="trofy-card-top"><span>#<?php echo$i+1;?></span><b><?php echo esc_html($r['class']);?></b></div><h3><?php echo esc_html($r['namePilot']);?></h3><p><?php echo esc_html($r['nameShturman']);?></p><div>🚙 <?php echo esc_html($r['car']);?></div><div>📍 <?php echo esc_html($r['city']);?></div><div>📞 <a href="tel:<?php echo esc_attr($r['tel']);?>"><?php echo esc_html($r['tel']);?></a></div></article><?php endforeach;?></div></div><?php return ob_get_clean();}
    public static function public_login():void{$u=!empty($_POST['redirect_to'])?esc_url_raw(wp_unslash($_POST['redirect_to'])):self::applications_url();if(!wp_validate_redirect($u,self::applications_url()))$u=self::applications_url();try{$s=self::settings();$p=isset($_POST['password'])?(string)wp_unslash($_POST['password']):'';$stored=$s?(string)$s['pass']:'';if(!$s||!$p||!$stored)throw new RuntimeException();$ok=wp_check_password($p,$stored);if(!$ok&&$stored!==''&&hash_equals($stored,$p)){$h=wp_hash_password($p);$st=self::db()->prepare('UPDATE appsettings SET pass=? WHERE id=1');$st->bind_param('s',$h);$st->execute();$ok=true;}if(!$ok)throw new RuntimeException();self::issue_public_access();self::redirect($u);}catch(Throwable $e){self::redirect($u,['login'=>'error']);}}
    public static function public_logout():void{check_admin_referer('trofy_public_logout');$u=!empty($_REQUEST['redirect_to'])?esc_url_raw(wp_unslash($_REQUEST['redirect_to'])):self::applications_url();if(!wp_validate_redirect($u,self::applications_url()))$u=self::applications_url();self::revoke_public_access();self::redirect($u);}
    public static function export_excel():void{$admin=is_user_logged_in()&&current_user_can('manage_options');if($admin)check_admin_referer('trofy_export');elseif(!self::has_public_access())wp_die('Доступ запрещён.','Доступ запрещён',['response'=>403]);try{$s=self::settings();if(!$s)wp_die('Настройки не найдены.');$rows=self::get_applications((int)$s['season_id'],(int)$s['event_id']);$p=__DIR__.'/PHPExcel/Classes/PHPExcel.php';if(!file_exists($p))wp_die('Библиотека PHPExcel не найдена.');require_once$p;$x=new PHPExcel();$sh=$x->setActiveSheetIndex(0);$sh->setTitle('Заявки');$sh->setCellValue('A1','Заявки — '.$s['event_name'].' '.$s['season_name']);$sh->mergeCells('A1:H1');$h=['№','Время','Класс','ФИО пилота','ФИО штурмана','Город','Автомобиль','Телефон'];foreach($h as $i=>$v)$sh->setCellValueByColumnAndRow($i,2,$v);foreach($rows as $i=>$r){$n=$i+3;$v=[$i+1,$r['formatted_time'],$r['class'],$r['namePilot'],$r['nameShturman'],$r['city'],$r['car'],$r['tel']];foreach($v as $c=>$z)$sh->setCellValueByColumnAndRow($c,$n,$z);}while(ob_get_level())ob_end_clean();nocache_headers();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="applications-'.date('Y-m-d-H-i').'.xlsx"');header('Cache-Control: max-age=0');PHPExcel_IOFactory::createWriter($x,'Excel2007')->save('php://output');exit;}catch(Throwable $e){error_log('Trofy export: '.$e->getMessage());wp_die('Не удалось сформировать Excel. Проверьте журнал ошибок.');}}
    private static function frontend_css():string{return'.trofy-form{max-width:620px;margin:30px auto;padding:28px;background:#fff;border:1px solid #e8e8e8;border-radius:18px}.trofy-input{margin:18px 0}.trofy-input label{display:block;font-weight:600;margin-bottom:7px}.trofy-input input,.trofy-login input{width:100%;box-sizing:border-box;padding:12px 14px;border:1px solid #d9dce1;border-radius:10px;font-size:16px}.trofy-radios{display:grid;grid-template-columns:1fr 1fr;gap:8px}.trofy-radios label{margin:0}.trofy-radios input{display:none}.trofy-radios span{display:block;padding:12px;border:1px solid #d9dce1;border-radius:10px;cursor:pointer;text-align:center}.trofy-radios input:checked+span{border-color:#222;background:#222;color:#fff}.trofy-submit,.trofy-login button{width:100%;padding:13px 18px;border:0;border-radius:10px;background:#222;color:#fff;font-size:16px;font-weight:700}.trofy-hp{position:absolute!important;left:-10000px!important}.trofy-closed,.trofy-alert{padding:25px;border-radius:14px;background:#f5f5f5}.trofy-login{max-width:420px;text-align:center;padding:35px 25px;margin:30px auto;border:1px solid #e8e8e8;border-radius:18px}.trofy-login form{display:grid;gap:12px;text-align:left}.trofy-public-head{display:flex;justify-content:space-between;gap:20px}.trofy-public-actions{display:flex;gap:8px}.trofy-public-actions a{padding:9px 13px;border:1px solid #ddd;border-radius:9px;text-decoration:none}.trofy-public-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.trofy-public-grid article{padding:18px;border:1px solid #e7e7e7;border-radius:14px;background:#fff}@media(max-width:700px){.trofy-radios,.trofy-public-grid{grid-template-columns:1fr}.trofy-public-head{flex-direction:column}}';}
    private static function admin_css():string{return'.trofy-admin{max-width:1400px}.trofy-admin-head{display:flex;justify-content:space-between;align-items:center;margin:25px 0}.trofy-settings-card{display:flex;gap:16px;align-items:end;background:#fff;border:1px solid #e2e4e7;border-radius:12px;padding:20px}.trofy-field{flex:1}.trofy-field label{display:block;font-weight:600;margin-bottom:6px}.trofy-field select,.trofy-field input{width:100%;min-height:40px}.trofy-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:16px 0}.trofy-stats div{background:#fff;border:1px solid #e2e4e7;border-radius:12px;padding:16px}.trofy-stats strong{display:block;font-size:25px}.trofy-toolbar{display:flex;gap:10px;margin:16px 0}.trofy-toolbar input{flex:1;min-height:40px}.trofy-table-wrap{background:#fff;border:1px solid #e2e4e7;border-radius:12px;overflow:auto}.trofy-table{width:100%;border-collapse:collapse}.trofy-table th,.trofy-table td{padding:12px;border-bottom:1px solid #eee;text-align:left}.trofy-table th{font-size:12px;color:#646970;background:#f6f7f7}@media(max-width:700px){.trofy-admin-head,.trofy-settings-card,.trofy-toolbar{display:block}.trofy-field,.trofy-save,.trofy-toolbar>*{width:100%;margin-bottom:10px}.trofy-stats{grid-template-columns:repeat(2,1fr)}.trofy-table thead{display:none}.trofy-table,.trofy-table tbody,.trofy-table tr{display:block}.trofy-table tr{background:#fff;border:1px solid #ddd;border-radius:12px;margin-bottom:10px}.trofy-table td{display:flex;justify-content:space-between;border:0}.trofy-table td:before{content:attr(data-label);font-weight:600;color:#646970}}';}
    private static function admin_js():string{return"jQuery(function($){const c=window.TrofyAppForms;$('#trofy-season').on('change',function(){$.post(c.ajaxurl,{action:'trofy_load_events',season_id:$(this).val(),nonce:c.nonce},function(r){let h='';if(r.success)r.data.forEach(e=>h+='<option value=\\\"'+e.event_id+'\\\">'+$('<div>').text(e.event_name).html()+'</option>');$('#trofy-event').html(h);});});$('#trofy-save').on('click',function(){const b=$(this);b.prop('disabled',true);$.post(c.ajaxurl,{action:'trofy_save_settings',season_id:$('#trofy-season').val(),event_id:$('#trofy-event').val(),pass:$('#trofy-pass').val(),nonce:c.nonce},function(r){b.prop('disabled',false);$('#trofy-admin-message').html('<div class=\\\"notice '+(r.success?'notice-success':'notice-error')+'\"><p>'+r.data+'</p></div>');if(r.success)$('#trofy-pass').val('');});});$('#trofy-search,#trofy-class').on('input change',function(){const q=($('#trofy-search').val()||'').toLowerCase(),cl=$('#trofy-class').val();$('#trofy-rows tr').each(function(){$(this).toggle(($(this).data('search')||'').toString().includes(q)&&(cl===''||$(this).data('class')===cl));});});$(document).on('click','.trofy-delete',function(){if(!confirm('Удалить заявку?'))return;const b=$(this);$.post(c.ajaxurl,{action:'trofy_delete_application',id:b.data('id'),nonce:c.nonce},function(r){if(r.success)b.closest('tr').remove();else alert(r.data||'Ошибка');});});});";}
}
